import { TODAY, people, stages, seed } from './data.mjs';
import { isDirector, canRead, canReadLinked, visible, canSeeUnitDetail, openTasks, overdue, moveSamples, setTaskState } from './domain.mjs';

const STORAGE='sud-me-wireframes-v1';
let state=seed(), actor=people.alex, region='All regions', ownerFilter='All accessible', recordTab='Activity', sampleTab='Catalogue', taskFilter='Open', directoryFilter='All', listQuery='', mailFilter='Needs filing', mobileOpen=false, modal=null, lastFocus=null, saveUnavailable=false;
try { const old=JSON.parse(localStorage.getItem(STORAGE)||'null'); if(old?.schema===1) state=old; } catch { saveUnavailable=true; }
const app=document.getElementById('app'), overlay=document.getElementById('overlay-root');
const e=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const date=v=>v?new Date(v.slice(0,10)+'T12:00:00').toLocaleDateString('en-GB',{day:'numeric',month:'short'}):'—';
const fullDate=v=>v?new Date(v.slice(0,10)+'T12:00:00').toLocaleDateString('en-GB',{day:'numeric',month:'long',year:'numeric'}):'—';
const money=(v,currency)=>`${currency} ${Number(v||0).toLocaleString('en-GB')}`;
const byId=(list,id)=>list.find(x=>x.id===id);
const person=id=>people[id]?.name||'Unassigned';
const orgName=id=>byId(state.organisations,id)?.name||'Internal project';
const tag=(text,tone='')=>`<span class="tag ${tone}">${e(text)}</span>`;
const audience=r=>r.audience==='directors'?'Directors only':r.audience==='shared'?'Shared team':`${person(r.owner)} + directors`;
const statusTone=s=>s==='Done'||s==='Available'||s==='Client'?'green':s==='Blocked'||s==='Needs our response'?'red':s==='Waiting'||s==='With client'||s==='Decision needed'?'amber':s==='In progress'||s==='Active'?'blue':s==='Prospect'?'violet':'';
const iconPaths={dashboard:'M3 3h7v7H3z M14 3h7v7h-7z M3 14h7v7H3z M14 14h7v7h-7z',directory:'M4 5h16v15H4z M8 5V3 M16 5V3 M4 10h16 M8 14h2 M14 14h2',prospects:'M4 4v16h16 M8 15l4-5 4 2 5-7',clients:'M3 21V7l9-4 9 4v14 M8 21v-5h8v5 M8 8v2 M16 8v2 M8 12v1 M16 12v1',projects:'M3 7h7l2 2h9v11H3z M3 7V4h7l2 3',tasks:'M8 5h13 M8 12h13 M8 19h13 M2 5l2 2 3-4 M2 12l2 2 3-4 M2 19l2 2 3-4',samples:'M3 7l9-4 9 4-9 5z M3 7v11l9 4 9-4V7 M12 12v10 M7 5l10 5',management:'M3 20h18 M6 16V9 M12 16V4 M18 16v-5',settings:'M12 8a4 4 0 1 0 0 8 4 4 0 0 0 0-8 M12 2v3 M12 19v3 M2 12h3 M19 12h3 M5 5l2 2 M17 17l2 2 M5 19l2-2 M17 7l2-2',mail:'M3 5h18v14H3z M3 5l9 7 9-7',search:'M10.5 3a7.5 7.5 0 1 0 0 15 7.5 7.5 0 0 0 0-15 M16 16l5 5',plus:'M12 5v14 M5 12h14',arrow:'M5 12h14 M14 7l5 5-5 5',back:'M19 12H5 M10 7l-5 5 5 5',chevron:'M9 5l7 7-7 7',down:'M5 9l7 7 7-7',clock:'M12 3a9 9 0 1 0 0 18 9 9 0 0 0 0-18 M12 7v5l3 2',alert:'M12 3L2 21h20z M12 9v5 M12 18h.01',check:'M5 12l4 4L19 6',close:'M6 6l12 12 M18 6L6 18',lock:'M5 10h14v11H5z M8 10V7a4 4 0 0 1 8 0v3 M12 14v3',menu:'M3 6h18 M3 12h18 M3 18h18',help:'M12 3a9 9 0 1 0 0 18 9 9 0 0 0 0-18 M9 9a3 3 0 1 1 4 3c-1 1-1 1-1 3 M12 18h.01',file:'M6 2h8l5 5v15H6z M14 2v6h5 M9 12h7 M9 16h7',visit:'M12 22s8-7 8-13A8 8 0 0 0 4 9c0 6 8 13 8 13z M12 6a3 3 0 1 0 0 6 3 3 0 0 0 0-6',refresh:'M20 7v5h-5 M4 17v-5h5 M5 7a8 8 0 0 1 14-1l1 6 M4 12l1 6a8 8 0 0 0 14-1',user:'M12 3a4 4 0 1 0 0 8 4 4 0 0 0 0-8 M4 21v-3a8 8 0 0 1 16 0v3',print:'M6 9V3h12v6 M6 17H3V9h18v8h-3 M6 14h12v7H6z'};
function icon(name){return `<svg class="icon" viewBox="0 0 24 24" aria-hidden="true"><path d="${iconPaths[name]||iconPaths.file}"/></svg>`;}
function btn(label,action,id='',style=''){return `<button class="button ${style}" data-action="${action}" data-id="${e(id)}">${e(label)}</button>`;}
function avatar(id){return `<span class="avatar ${id==='alex'||id==='sameh'?'rose':''}" title="${e(person(id))}">${e(people[id]?.initials||'?')}</span>`;}
function entity(o){return `<div class="entity"><span class="entity-icon ${e(o.colour)}">${e(o.short)}</span><div><button class="entity-name" data-action="open-org" data-id="${e(o.id)}">${e(o.name)}</button><div class="entity-meta">${e(o.city)} · ${e(o.country)}</div></div></div>`;}
function empty(title,text,action=''){return `<div class="empty">${icon('check')}<h3>${e(title)}</h3><p>${e(text)}</p>${action}</div>`;}
function route(){return (location.hash.slice(1)||'/dashboard').split('/').filter(Boolean);}
function go(path){listQuery='';recordTab='Activity';mobileOpen=false;if(location.hash===`#${path}`)render();else location.hash=path;}
function save(message){try{localStorage.setItem(STORAGE,JSON.stringify(state));saveUnavailable=false;}catch{saveUnavailable=true;}render();if(message)toast(message+(saveUnavailable?' Changes remain only in this tab.':''));}
let toastTimer;function toast(message){const el=document.getElementById('toast');el.textContent=message;el.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('show'),4000);}
function recordCountry(r){return r.country||byId(state.organisations,r.org)?.country||byId(state.projects,r.project)?.country||'UAE';}
function accessible(records){return records.filter(r=>canReadLinked(actor,r,state));}
function scoped(records){return accessible(records).filter(r=>(region==='All regions'||recordCountry(r)===region)&&(ownerFilter==='All accessible'||ownerFilter==='Shared'&&r.audience==='shared'||r.owner===ownerFilter.toLowerCase()));}
function navLink(id,label,count){return `<a href="#/${id}" class="${route()[0]===id?'active':''}" ${route()[0]===id?'aria-current="page"':''}>${icon(id)}<span>${label}</span>${count?`<span class="nav-count">${count}</span>`:''}</a>`;}
function layout(content){const nav=[['dashboard','Dashboard'],['directory','Directory'],['prospects','Prospects'],['clients','Clients'],['projects','Projects'],['tasks','Tasks'],['samples','Samples']];return `<div class="shell"><aside class="sidebar ${mobileOpen?'open':''}"><a class="brand" href="#/dashboard"><span class="brand-mark">SUD</span><span class="brand-name">Middle East<span>Management hub</span></span></a><div class="nav-title">Workspace</div><nav class="nav" aria-label="Main navigation">${nav.map(([id,label])=>navLink(id,label,id==='tasks'?openTasks(accessible(state.tasks)).length:null)).join('')}</nav>${isDirector(actor)?`<div class="nav-divider"></div><div class="nav-title">Directors</div><nav class="nav" aria-label="Management">${navLink('management','Management')}</nav>`:''}<div class="sidebar-bottom"><nav class="nav" aria-label="Utilities"><a href="#/filing" class="${route()[0]==='filing'?'active':''}">${icon('mail')}Needs filing<span class="nav-count">${accessible(state.messages).filter(m=>!m.org).length}</span></a>${isDirector(actor)?navLink('settings','Connections'):''}<a href="#" data-action="help">${icon('help')}Preview guide</a><a href="https://github.com/SchoolUniformDirect/sud-me-crm-preview/issues/new?template=feedback.yml" target="_blank" rel="noopener noreferrer">${icon('help')}Leave feedback</a></nav><div class="profile">${avatar(actor.id)}<div><strong class="small-text">${e(actor.fullName)}</strong><div class="meta">${isDirector(actor)?'Director · all regions':actor.country+' executive'}</div></div></div></div></aside><button class="mobile-dismiss" data-action="menu" aria-label="Close navigation"></button><div class="workspace"><header class="topbar"><button class="mobile-menu" data-action="menu" aria-label="Open navigation">${icon('menu')}</button><div class="crumb">SUD portal <span>/ Middle East</span></div><div class="searchbox">${icon('search')}<input id="global-search" type="search" aria-label="Search accessible records" placeholder="Search schools, projects, samples…" autocomplete="off"><div id="search-results"></div></div><div class="role-switch"><label for="role">Preview as</label><select id="role">${Object.values(people).map(p=>`<option value="${p.id}" ${actor.id===p.id?'selected':''}>${p.name}${p.role==='director'?' · Director':''}</option>`).join('')}</select></div></header><div class="demo-strip"><span class="demo-label"><span class="dot"></span>Interactive wireframes · fictional data · ${saveUnavailable?'changes only in this tab':'changes saved on this device'}</span><button class="text-btn" data-action="reset">Reset examples</button></div><main id="main" class="page" tabindex="-1">${content}<footer class="footer-note"><span>SUD Middle East · Design preview 0.1</span><span>Example working day: Friday 6 November 2026</span></footer></main></div></div>`;}
function heading(title,subtitle,actions=''){return `<div class="page-head"><div><div class="eyebrow">Middle East workspace</div><h1>${e(title)}</h1><p>${e(subtitle)}</p></div><div class="head-actions">${actions}</div></div>`;}
function filters(extra=''){return `<div class="filters"><div class="segments" role="group" aria-label="Work owner">${(isDirector(actor)?['All accessible','Sameh','Latif','Shared']:['All accessible','Shared']).map(v=>`<button data-action="owner-filter" data-id="${v}" class="${ownerFilter===v?'active':''}">${v==='All accessible'?'All accessible work':v}</button>`).join('')}</div><div class="filter-tools">${extra}<select class="filter-select" id="region" aria-label="Region">${['All regions','UAE','Saudi Arabia'].map(v=>`<option ${v===region?'selected':''}>${v}</option>`).join('')}</select></div></div>`;}
function taskRow(t){const late=overdue(t,TODAY);return `<div class="attention-row"><div class="attention-icon ${late?'rose':t.owner==='bilal'||t.owner==='alex'?'blue':''}">${icon(late?'alert':t.status==='Waiting'?'clock':'tasks')}</div><div class="row-main"><button class="entity-name" data-action="task" data-id="${t.id}">${e(t.title)}</button><div class="detail">${e(t.org?orgName(t.org):byId(state.projects,t.project)?.name||'General work')} · ${person(t.owner)}</div><div class="row-bottom">${tag(late?'Overdue · '+date(t.due):t.status==='Waiting'?'Review · '+date(t.due):date(t.due),late?'red':t.due===TODAY?'amber':'')}${t.audience==='directors'?tag('Directors only','rose'):''}${t.audience==='shared'?tag('Shared team','blue'):''}</div></div><div class="row-end">${btn('Open','task',t.id,'small')}</div></div>`;}
function dashboard(){const tasks=openTasks(scoped(state.tasks)),late=tasks.filter(t=>overdue(t,TODAY)),due=tasks.filter(t=>t.due===TODAY),requests=scoped(state.messages).filter(m=>m.state==='Needs our response'&&m.direction==='Incoming'),loans=state.units.filter(u=>u.status==='With client'&&u.due<TODAY&&canSeeUnitDetail(actor,u,state.organisations));const attention=[...tasks].sort((a,b)=>a.due.localeCompare(b.due));return `${heading(isDirector(actor)?`Good afternoon, ${actor.name}`:'My day',isDirector(actor)?'A clear view of the work that needs your attention.':'Your priorities, follow-ups and commitments in one place.',`<button class="button primary" data-action="add-task">${icon('plus')}New task</button>`)}${filters()}<div class="stats">${[[late.length,'Overdue tasks','Commitments needing follow-up','tasks','alert','alert'],[due.length,'Due today','Including waiting items to review','tasks','clock',''],[requests.length,'Open client requests','Based on example communications','filing','mail',''],[loans.length,'Overdue sample loans','Items to arrange collection for','samples','samples','alert']].map(([n,label,caption,path,ic,tone])=>`<button class="stat" data-action="stat" data-id="${path}" data-label="${label}"><div class="stat-label">${label}${icon(ic)}</div><div class="value">${n}</div><div class="caption ${tone}">${caption}</div></button>`).join('')}</div><div class="dashboard-grid"><div class="stack"><section class="card"><div class="card-head"><div><h2>${isDirector(actor)?'Needs attention':'Your next actions'}</h2><p>Named actions, clear ownership and evidence.</p></div><a class="text-btn" href="#/tasks">View all tasks →</a></div>${attention.length?attention.slice(0,5).map(taskRow).join(''):empty('Nothing due here','Your filtered work has no open actions.')}</section><section class="card"><div class="card-head"><h2>Recent client activity</h2><a href="#/clients" class="text-btn">View clients →</a></div>${scoped(state.messages).filter(m=>m.org&&m.direction!=='Internal').sort((a,b)=>b.date.localeCompare(a.date)).slice(0,2).map(m=>`<div class="attention-row"><div class="attention-icon blue">${icon('mail')}</div><div class="row-main"><button class="entity-name" data-action="email" data-id="${m.id}">${e(m.subject)}</button><div class="detail">${e(orgName(m.org))} · ${e(m.from)} · ${date(m.date)}</div></div></div>`).join('')||empty('No recorded activity','New communications will appear here.')}</section></div><div class="stack">${isDirector(actor)?`<section class="card summary-card"><div class="card-head"><h2>Directors’ daily brief</h2>${icon('lock')}</div><div class="card-body"><p class="intro">See the progress, promises and decisions behind the day’s communications.</p><div class="summary-mini"><div><strong>${scoped(state.tasks).filter(t=>['alex','bilal'].includes(t.owner)&&t.status!=='Done').length}</strong><span>decisions to review</span></div><div><strong>2</strong><span>executive summaries</span></div></div><a class="button" href="#/management">Read the example brief ${icon('arrow')}</a></div></section>`:`<section class="card summary-card"><div class="card-head"><h2>Keep the next step clear</h2>${icon('check')}</div><div class="card-body"><p class="intro">Complete a task, set a review date while you wait, or flag a blocker. Your work stays visible without a separate status report.</p><a class="button" href="#/tasks">Open my work ${icon('arrow')}</a></div></section>`}<section class="card"><div class="card-head"><h2>Coming up</h2>${icon('directory')}</div>${scoped(state.projects).flatMap(p=>p.milestones.filter(m=>m[2]!=='Done').map(m=>({p,m}))).sort((a,b)=>a.m[1].localeCompare(b.m[1])).slice(0,3).map(({p,m})=>`<a href="#/project/${p.id}" class="timeline-row"><div class="date-box"><strong>${new Date(m[1]+'T12:00:00').getDate()}</strong>${date(m[1]).split(' ')[1]}</div><div><p>${e(m[0])}</p><small>${e(p.name)}</small></div></a>`).join('')}</section></div></div><div class="connection-strip">${icon('mail')}<div><p>Live email connections are awaiting setup</p><span>This preview demonstrates filing, follow-ups and coverage warnings using examples.</span></div><a class="text-btn" href="#/${isDirector(actor)?'settings':'filing'}">${isDirector(actor)?'View setup':'Needs filing'} →</a></div>`;}
function directory(clients=false){const filtered=scoped(state.organisations).filter(o=>(!clients||['Client','Past client'].includes(o.status))&&(directoryFilter==='All'||directoryFilter==='Schools'&&o.type.startsWith('School')||directoryFilter==='Businesses'&&o.type==='Business')&&`${o.name} ${o.city} ${o.contact}`.toLowerCase().includes(listQuery.toLowerCase()));return `${heading(clients?'Clients':'Directory',clients?'Current and past relationships, with their complete history.':'One place for schools, businesses and the people you work with.',`<button class="button primary" data-action="add-org">${icon('plus')}Add ${clients?'client':'organisation'}</button>`)}<div class="filters"><div class="segments">${['All','Schools','Businesses'].map(v=>`<button data-action="directory-filter" data-id="${v}" class="${directoryFilter===v?'active':''}">${v}</button>`).join('')}</div><div class="filter-tools"><input class="list-search" id="list-search" type="search" value="${e(listQuery)}" placeholder="Search names, contacts or cities…" aria-label="Search directory"><select id="region" class="filter-select" aria-label="Region">${['All regions','UAE','Saudi Arabia'].map(v=>`<option ${region===v?'selected':''}>${v}</option>`).join('')}</select></div></div><section class="card"><div class="table-wrap"><table class="table"><thead><tr><th>${clients?'Client':'Organisation'}</th><th>Relationship</th><th>Owner / access</th><th>Next action</th><th>Last contact</th><th></th></tr></thead><tbody>${filtered.map(o=>`<tr><td>${entity(o)}</td><td>${tag(o.status,statusTone(o.status))}</td><td><div>${person(o.owner)}</div><div class="entity-meta">${e(audience(o))}</div></td><td>${e(o.next)}<div class="entity-meta">${o.due?date(o.due):'Research only'}</div></td><td class="nowrap">${date(o.lastContact)}</td><td><button class="icon-button" aria-label="Open ${e(o.name)}" data-action="open-org" data-id="${o.id}">${icon('chevron')}</button></td></tr>`).join('')}</tbody></table></div>${!filtered.length?empty('No matching records','Try another search or add an organisation.'):''}<div class="table-footer">${filtered.length} accessible ${clients?'clients':'organisations'} · one record throughout the relationship</div></section>`;}
function orgDetail(id){const o=byId(state.organisations,id);if(!canRead(actor,o))return noAccess();const messages=accessible(state.messages).filter(m=>m.org===id).sort((a,b)=>b.date.localeCompare(a.date));const notes=accessible(state.notes).filter(n=>n.org===id);const tasks=accessible(state.tasks).filter(t=>t.org===id);const samples=state.units.filter(u=>u.org===id);let body='';if(recordTab==='Activity'){body=`<section class="card"><div class="card-head"><h2>Activity timeline</h2>${btn('Add note','add-note',id,'small')}</div>${notes.map(n=>`<div class="activity-item"><div class="activity-icon">${icon('file')}</div><div class="activity-content"><div class="activity-meta"><span>${e(n.kind)} · ${person(n.author||n.owner)}</span><span>${date(n.date)}</span></div><p dir="auto">${e(n.body)}</p></div></div>`).join('')}${messages.map(m=>`<article class="activity-item"><div class="activity-icon">${icon(m.direction==='Internal'?'lock':'mail')}</div><div class="activity-content"><div class="activity-meta"><span>${e(m.direction)} · ${e(m.from)}</span><span>${date(m.date)}</span></div><h3>${e(m.subject)}</h3><p dir="auto">${e(m.body.slice(0,180))}${m.body.length>180?'…':''}</p><div class="actions">${tag(m.state,statusTone(m.state))}${m.audience==='directors'?tag('Directors only','rose'):''}<button class="text-btn" data-action="email" data-id="${m.id}">Open email →</button></div></div></article>`).join('')}${!messages.length&&!notes.length?empty('The history starts here','Add a meeting note or record a communication.'):''}</section>`;}else if(recordTab==='Contacts'){body=`<section class="card"><div class="card-head"><h2>People and contact points</h2></div>${o.contact?`<div class="contact-card"><span class="avatar rose">${e(o.contact.split(' ').map(n=>n[0]).join(''))}</span><div><h3>${e(o.contact)}</h3><p>${e(o.position)}</p><p>${e(o.email)}</p><p>${e(o.phone)}</p></div></div>`:empty('No contacts yet','Add contact information through Edit details.',btn('Edit details','edit-org',id))}</section>`;}else if(recordTab==='Work'){body=`<section class="card"><div class="card-head"><h2>Open work</h2>${btn('New task','add-task',id,'small')}</div>${openTasks(tasks).map(taskRow).join('')||empty('No open tasks','Add the next action for this relationship.',btn('Add task','add-task',id))}</section>`;}else if(recordTab==='Samples'){body=`<section class="card"><div class="card-head"><h2>Samples with this client</h2>${btn('Issue samples','move','issue','small')}</div>${samples.length?sampleHoldings(samples):empty('No samples on loan','Client handovers will appear here with their return dates.')}</section>`;}else{body=`<section class="card"><div class="card-head"><h2>Files and delivery notes</h2></div>${state.documents.filter(d=>d.client===o.name).map(d=>`<div class="attention-row">${icon('file')}<div class="row-main"><h3>${e(d.number)}</h3><p class="muted small-text">Example sample delivery note · ${date(d.date)}</p></div>${btn('View','note',d.number,'small')}</div>`).join('')||empty('No files in this example','Delivery notes generated in the sample workflow appear here. Document uploads will be connected during the application build.')}</section>`;}return `<button class="back-link" data-action="back-clients">${icon('back')}Back to directory</button><div class="page-head"><div class="record-header"><span class="entity-icon ${o.colour}">${o.short}</span><div><h1>${e(o.name)}</h1><div class="record-meta"><span>${e(o.type)} · ${e(o.city)}, ${e(o.country)}</span>${tag(o.status,statusTone(o.status))}${tag(audience(o),o.audience==='shared'?'blue':'')}</div></div></div><div class="head-actions">${btn('Edit details','edit-org',o.id)}${isDirector(actor)?btn('Sharing','sharing',o.id):''}</div></div><div class="page-tabs">${['Activity','Contacts','Work','Files','Samples'].map(t=>`<button data-action="record-tab" data-id="${t}" class="${recordTab===t?'active':''}">${t}</button>`).join('')}</div><div class="record-grid"><div><div class="record-next"><div><span>Next action · ${person(o.owner)}</span><p>${e(o.next)}</p></div>${o.due?tag(date(o.due),o.due<TODAY?'red':'rose'):tag('Research record')}</div>${body}</div><aside class="stack"><section class="card"><div class="card-head"><h2>Relationship overview</h2></div><div class="card-body"><dl class="detail-list"><div><dt>Accountable owner</dt><dd>${person(o.owner)}</dd></div><div><dt>Last recorded client contact</dt><dd>${date(o.lastContact)}</dd></div><div><dt>Open tasks</dt><dd>${openTasks(tasks).length}</dd></div>${o.contract?`<div><dt>Contract end date</dt><dd>${fullDate(o.contract)}</dd></div><div><dt>Review / notice attention</dt><dd>${fullDate(o.review)}</dd></div>`:''}<div><dt>About the relationship</dt><dd class="info-text" dir="auto">${e(o.notes)||'No notes recorded.'}</dd></div></dl></div></section><section class="card"><div class="card-body"><h3>Capture coverage</h3><p class="info-text spaced">Example messages only. Outlook is not connected in this preview.</p><button class="text-btn spaced" data-action="manual-email" data-id="${o.id}">Record an example email →</button></div></section></aside></div>`;}
function prospects(){const opps=scoped(state.opportunities);return `${heading('Prospects','Every opportunity has an owner and a clear next step.',`<button class="button primary" data-action="add-opportunity">${icon('plus')}New opportunity</button>`)}${filters()}<div class="board">${stages.slice(0,5).map(stage=>{const entries=opps.filter(o=>o.stage===stage);return `<section class="board-column"><div class="board-title">${stage}<span class="board-count">${entries.length}</span></div>${entries.map(o=>`<button class="opportunity" data-action="opportunity" data-id="${o.id}">${tag(o.country==='UAE'?'UAE':'Saudi Arabia',o.country==='UAE'?'rose':'blue')}<h3>${e(orgName(o.org))}</h3><div class="scope">${e(o.title)}</div><div class="money">${money(o.value,o.currency)} <small class="muted">est.</small></div><div class="next">Next: ${e(o.next)}</div><div class="due">${tag(date(o.due))}<span class="small-text muted">${person(o.owner)}</span></div></button>`).join('')||`<p class="muted small-text" style="padding:10px 3px">No opportunities at this stage.</p>`}</section>`;}).join('')}</div><div class="notice">Estimated annual values stay in their original currency. A group opportunity is counted once.</div>${opps.some(o=>['Won','Lost'].includes(o.stage))?`<section class="card"><div class="card-head"><h2>Closed opportunities</h2></div>${opps.filter(o=>['Won','Lost'].includes(o.stage)).map(o=>`<div class="attention-row"><div class="row-main"><h3>${e(o.title)}</h3><p class="muted small-text">${e(orgName(o.org))}</p></div>${tag(o.stage,o.stage==='Won'?'green':'')}${btn('Open','opportunity',o.id,'small')}</div>`).join('')}</section>`:''}`;}
function projects(){const projects=scoped(state.projects);return `${heading('Projects','Client delivery and internal work, with clear milestones.',`<button class="button primary" data-action="add-project">${icon('plus')}New project</button>`)}${filters()}<div class="project-grid">${projects.map(p=>`<article class="card project-card"><div class="project-top"><span class="attention-icon blue">${icon('projects')}</span>${tag(p.status,statusTone(p.status))}</div><h3>${e(p.name)}</h3><p>${e(p.description)}</p><div class="row-bottom">${tag(p.country)}${tag(audience(p),p.audience==='shared'?'blue':'')}</div><div class="next-box"><span>Next milestone</span><strong>${e(p.next)}</strong></div><div class="footer"><span class="muted">${person(p.owner)} · ${date(p.target)}</span><a class="text-btn" href="#/project/${p.id}">Open project →</a></div></article>`).join('')}</div>${!projects.length?empty('No projects in this view','Choose another filter or add a project.'):''}`;}
function projectDetail(id){const p=byId(state.projects,id);if(!canRead(actor,p))return noAccess();const tasks=accessible(state.tasks).filter(t=>t.project===id);return `<button class="back-link" data-action="back-projects">${icon('back')}Back to projects</button>${heading(p.name,p.description,btn('New task','project-task',id,'primary'))}<div class="record-meta" style="margin-bottom:22px">${tag(p.status,statusTone(p.status))}${tag(audience(p),p.audience==='shared'?'blue':'')}<span>Owner: ${person(p.owner)} · Target ${fullDate(p.target)}</span></div><div class="record-grid"><div class="stack"><section class="card"><div class="card-head"><h2>Milestones and deadlines</h2></div><ol class="milestones">${p.milestones.map((m,i)=>`<li><span class="step ${m[2]==='Done'?'done':''}">${m[2]==='Done'?icon('check'):i+1}</span><div class="step-content"><p>${e(m[0])}</p><small>${date(m[1])}</small></div>${tag(m[2],statusTone(m[2]))}</li>`).join('')}</ol></section><section class="card"><div class="card-head"><h2>Project tasks</h2></div>${openTasks(tasks).map(taskRow).join('')||empty('No open tasks','Add the next action for this project.')}</section></div><aside class="stack"><section class="card"><div class="card-body"><h3>Next action</h3><p class="info-text spaced">${e(p.next)}</p>${p.status==='Blocked'?`<div class="coverage spaced">${icon('alert')}Access arrangements need to be confirmed before the next milestone.</div>`:''}</div></section>${p.audience==='shared'?`<section class="card"><div class="card-body"><h3>Shared project</h3><p class="info-text spaced">Sameh and Latif can contribute to this project. Latif remains accountable for delivery. Their other private work stays separate.</p></div></section>`:''}</aside></div>`;}
function tasksPage(){const all=scoped(state.tasks);const tasks=all.filter(t=>taskFilter==='All'||taskFilter==='Open'&&!['Done','Cancelled'].includes(t.status)||taskFilter==='Overdue'&&overdue(t,TODAY)||taskFilter==='Today'&&t.due===TODAY&&!['Done','Cancelled'].includes(t.status)||taskFilter===t.status);return `${heading(isDirector(actor)?'Team tasks':'Tasks','One owner, one next action and a date to follow up.',`<button class="button primary" data-action="add-task">${icon('plus')}New task</button>`)}${filters()}<div class="page-tabs">${['Open','Overdue','Today','Waiting','Done','All'].map(t=>`<button data-action="task-filter" data-id="${t}" class="${taskFilter===t?'active':''}">${t}</button>`).join('')}</div><section class="card"><div class="table-wrap"><table class="table"><thead><tr><th></th><th>Action</th><th>Owner</th><th>Due / review</th><th>Status</th><th></th></tr></thead><tbody>${tasks.sort((a,b)=>a.due.localeCompare(b.due)).map(t=>`<tr><td><button class="task-check ${t.status==='Done'?'done':''}" data-action="complete-task" data-id="${t.id}" ${t.status==='Done'?'disabled':''} aria-label="Complete ${e(t.title)}">${t.status==='Done'?icon('check'):''}</button></td><td><button class="entity-name" data-action="task" data-id="${t.id}">${e(t.title)}</button><div class="entity-meta">${e(t.org?orgName(t.org):byId(state.projects,t.project)?.name||'General work')}</div></td><td>${person(t.owner)}</td><td>${tag(date(t.due),overdue(t,TODAY)?'red':t.due===TODAY?'amber':'')}</td><td>${tag(t.status,statusTone(t.status))}</td><td>${btn('Open','task',t.id,'small')}</td></tr>`).join('')}</tbody></table></div>${!tasks.length?empty('No tasks in this view','Choose another status or add your next action.'):''}</section>`;}
function garment(p){return `<svg class="garment" viewBox="0 0 150 160" aria-label="Illustration of ${e(p.name)}" role="img"><path d="M48 22L25 36 7 68l24 14 13-20v85h62V62l13 20 24-14-18-32-23-14-11 12H59z" fill="${p.hex}" stroke="#00000015" stroke-width="1.5"/><path d="M48 22l11 12 16 5 16-5 11-12-16-8H64z" fill="${p.hex}" stroke="#ffffff30"/><path d="M64 14q11 16 22 0" fill="#172536" opacity=".3"/>${p.kind==='polo'?'<path d="M64 14l-5 20 12-9 4 14 4-14 12 9-5-20" fill="#ffffff20"/><path d="M75 26v28" stroke="#ffffff45"/><circle cx="78" cy="42" r="1" fill="#eee"/>':p.kind==='blazer'?'<path d="M64 15l-7 38 18 18 18-18-7-38 M75 71v76" fill="none" stroke="#ffffff40"/><path d="M52 96h14 M87 96h14" stroke="#ffffff40"/><circle cx="79" cy="85" r="1.5" fill="#bca881"/><circle cx="79" cy="105" r="1.5" fill="#bca881"/>':p.kind==='hoodie'?'<path d="M59 34Q36 6 75 5q39 1 16 29 M65 35v33 M85 35v33 M59 106h32l8 25H51z" fill="none" stroke="#ffffff55"/>':'<path d="M59 25q16 22 32 0" fill="none" stroke="#ffffff50" stroke-width="4"/>'}<path d="M47 140h56" stroke="#ffffff25"/><path d="M44 61l5 65 M106 61l-5 65" stroke="#00000010"/></svg>`;}
function sampleHoldings(units){return `<div class="table-wrap"><table class="table"><thead><tr><th>Sample</th><th>Size / colour</th><th>With / location</th><th>Expected return</th><th>Status</th></tr></thead><tbody>${units.map(u=>{const p=byId(state.products,u.product),details=canSeeUnitDetail(actor,u,state.organisations);return `<tr><td><button class="entity-name" data-action="product" data-id="${p.id}">${e(p.name)}</button><div class="entity-meta">${p.ref}${details?' · '+u.id:''}</div></td><td>${e(u.size)} · ${e(p.colour)}</td><td>${details?e(u.holder):'Held elsewhere'}</td><td>${details?tag(date(u.due),u.due&&u.due<TODAY?'red':''):'—'}</td><td>${tag(u.status,statusTone(u.status))}</td></tr>`}).join('')}</tbody></table></div>`;}
function samples(){const products=state.products.filter(p=>`${p.name} ${p.ref} ${p.colour} ${p.tags.join(' ')} ${p.sizes.join(' ')}`.toLowerCase().includes(listQuery.toLowerCase()));const loans=state.units.filter(u=>u.status!=='Available'&&canSeeUnitDetail(actor,u,state.organisations));return `${heading('Samples','Find what we already have. Know where every sample is.',`<button class="button" data-action="move" data-id="return">${icon('back')}Return</button><button class="button" data-action="move" data-id="take">Take samples</button><button class="button primary" data-action="move" data-id="issue">${icon('plus')}Issue to client</button>`)}<div class="page-tabs">${['Catalogue','On loan','Movement history','Delivery notes'].map(t=>`<button data-action="sample-tab" data-id="${t}" class="${sampleTab===t?'active':''}">${t}</button>`).join('')}</div>${sampleTab==='Catalogue'?`<div class="filters"><div class="small-text muted">${state.products.length} products · ${state.units.filter(u=>u.status==='Available').length} physical samples available</div><input class="list-search" id="list-search" value="${e(listQuery)}" type="search" aria-label="Search samples" placeholder="Search name, reference, size or tag…"></div><div class="products">${products.map(p=>{const units=state.units.filter(u=>u.product===p.id),available=units.filter(u=>u.status==='Available').length;return `<button class="product-card" data-action="product" data-id="${p.id}"><div class="product-art">${tag(p.supply)}${garment(p)}</div><div class="product-body"><div class="product-ref">${p.ref}</div><h3>${p.name}</h3><div class="variant">${p.colour} · ${p.sizes.join(' / ')}</div><div class="product-stock"><strong>${available} available</strong><span>${units.length} samples in total</span></div></div></button>`}).join('')}</div>${!products.length?empty('No matching samples','Try another reference, colour, size or product name.'):''}<section class="card loans-list"><div class="card-head"><div><h2>Returns needing attention</h2><p>Visible loans with a return date before the example working day.</p></div>${btn('Record return','move','return','small')}</div>${loans.some(u=>u.due<TODAY)?sampleHoldings(loans.filter(u=>u.due<TODAY)):empty('No overdue returns','Every visible loan is within its expected return date.')}</section>`:sampleTab==='On loan'?`<section class="card"><div class="card-head"><h2>Samples with colleagues and clients</h2><span class="small-text muted">${loans.length} visible holdings</span></div>${loans.length?sampleHoldings(loans):empty('No visible loans','Take a sample or issue one to a client to try this workflow.')}</section>`:sampleTab==='Movement history'?`<section class="card"><div class="card-head"><h2>Recorded example movements</h2></div>${state.movements.filter(m=>isDirector(actor)||m.actor===actor.id).reverse().map(m=>`<div class="attention-row"><div class="attention-icon blue">${icon('samples')}</div><div class="row-main"><h3>${e(m.unit)} · ${e(m.kind==='take'?'Taken by colleague':m.kind==='issue'?'Issued to client':'Returned')}</h3><p class="muted small-text">${e(m.from)} → ${e(m.to)} · ${person(m.actor)} · ${date(m.date)}</p></div></div>`).join('')||empty('No movements recorded yet','Try taking, issuing or returning an example sample. Every movement will remain in this history.')}</section>`:`<section class="card"><div class="card-head"><h2>Client delivery notes</h2></div>${state.documents.filter(d=>visible(actor,state.organisations).some(o=>o.name===d.client)).map(d=>`<div class="attention-row">${icon('file')}<div class="row-main"><h3>${d.number}</h3><p class="muted small-text">${e(d.client)} · ${date(d.date)} · ${d.lines.length} samples</p></div>${tag('Example · not emailed')}${btn('View','note',d.number,'small')}</div>`).join('')||empty('No delivery notes yet','Issue an example sample to a client to generate a safe handover note.')}</section>`}<div class="notice">Product illustrations are placeholders. The shared catalogue shows availability; restricted client and loan details stay out of other executives’ views.</div>`;}
function management(){if(!isDirector(actor))return noAccess();return `${heading('Directors’ daily brief','A short, evidence-led view of progress and the next decisions.',tag('Alex + Bilal only','rose'))}<div class="coverage">${icon('alert')}<div>Example report · live email coverage has not been established<small>This illustrates the report layout. It makes no claim about actual staff activity or performance.</small></div></div><div class="management-grid"><section class="card digest"><div class="person">${avatar('sameh')}<div><h2>Sameh</h2><p class="small-text muted">UAE · illustrative daily activity</p></div></div><div class="digest-section"><h4>Progress</h4><ul><li>Cedar School’s sample request was acknowledged and a visit is being arranged. <button class="evidence" data-action="email" data-id="e-cedar-reply">View communication ↗</button></li><li>Horizon Group requested one proposal covering three campuses. <button class="evidence" data-action="email" data-id="e-horizon">View request ↗</button></li></ul></div><div class="digest-section"><h4>Commitments to follow up</h4>${openTasks(state.tasks).filter(t=>t.owner==='sameh').slice(0,3).map(t=>`<div class="attention-row" style="padding:10px 0"><div class="row-main"><button class="entity-name" data-action="task" data-id="${t.id}">${e(t.title)}</button><div class="entity-meta">${date(t.due)} · ${e(t.status)}</div></div></div>`).join('')||'<p class="small-text muted">No open example commitments.</p>'}</div><div class="digest-section"><h4>Director decision</h4><p class="small-text">Review the proposed logo setup cost before confirming the commercial position. <button class="evidence" data-action="email" data-id="e-private">Private source ↗</button></p></div><div class="digest-foot">Source: fictional communications and current example tasks. No real mailbox data.</div></section><section class="card digest"><div class="person">${avatar('latif')}<div><h2>Latif</h2><p class="small-text muted">Saudi Arabia · illustrative daily activity</p></div></div><div class="digest-section"><h4>Outstanding request</h4><ul><li>Oasis Academy is awaiting confirmed launch dates. An acknowledgement was recorded, but the request remains open. <button class="evidence" data-action="email" data-id="e-oasis">View request ↗</button></li></ul></div><div class="digest-section"><h4>Projects and dependencies</h4><ul><li>Riyadh shop signage needs Bilal’s approval. <a class="evidence" href="#/project/refit">Open shared project ↗</a></li><li>Warehouse access arrangements are blocking the next milestone. <a class="evidence" href="#/project/warehouse">Open project ↗</a></li></ul></div><div class="digest-section"><h4>Commitments to follow up</h4>${openTasks(state.tasks).filter(t=>t.owner==='latif').map(t=>`<div class="attention-row" style="padding:10px 0"><div class="row-main"><button class="entity-name" data-action="task" data-id="${t.id}">${e(t.title)}</button><div class="entity-meta">${date(t.due)} · ${e(t.status)}</div></div></div>`).join('')||'<p class="small-text muted">No open example commitments.</p>'}</div><div class="digest-foot">Shared-mailbox messages are attributed to the mailbox where the individual sender is unverified.</div></section></div><div class="notice">Daily delivery time and working calendars will be configured during setup. This preview does not send or schedule any reports.</div>`;}
function filing(){const messages=accessible(state.messages).filter(m=>mailFilter==='Needs filing'?!m.org:m.state==='Needs our response'&&m.direction==='Incoming');return `${heading('Communication review','Keep incoming requests and uncertain matches moving.',btn('Record an email','manual-email','','primary'))}<div class="page-tabs">${['Needs filing','Open requests'].map(t=>`<button data-action="mail-filter" data-id="${t}" class="${mailFilter===t?'active':''}">${t}</button>`).join('')}</div>${messages.map(m=>`<article class="card queue-card"><span class="attention-icon blue">${icon('mail')}</span><div class="queue-body"><h3>${e(m.subject)}</h3><div class="small-text muted">${e(m.from)} · ${e(m.mailbox)} · ${date(m.date)}</div><p>${e(m.body)}</p><div class="row-bottom">${tag(m.org?'Needs our response':'Match needs review','amber')}${tag(audience(m))}</div></div>${btn(m.org?'Review request':'Review & file',m.org?'email':'file-email',m.id)}</article>`).join('')||empty('Nothing waiting in this view','New requests and uncertain matches will appear here.')}<div class="notice">A broad domain match cannot choose between campuses. Filing a message never automatically widens its audience.</div>`;}
function settings(){if(!isDirector(actor))return noAccess();const mailboxes=[['sameh@sud.ae','UAE executive'],['latif@sud.me','Saudi executive'],['info@sud.ae','UAE general enquiries'],['info@sud.me','Saudi general enquiries'],['bilal@sud.me','Director'],['exec@sud.ae','UAE executive office'],['a.gani@sud.co.uk','Director · relevant Middle East scope']];return `${heading('Email connections','Coverage should be visible, reliable and easy to check.')}<div class="settings-grid"><section class="card"><div class="card-head"><h2>Required mailbox sources</h2>${tag('Setup pending','amber')}</div><div class="table-wrap"><table class="table"><thead><tr><th>Mailbox</th><th>Capture route</th><th>Status</th></tr></thead><tbody>${mailboxes.map(([email,scope])=>`<tr><td><strong>${email}</strong><div class="entity-meta">${scope}</div></td><td class="muted">To be verified</td><td>${tag('Not connected')}</td></tr>`).join('')}</tbody></table></div></section><aside class="card"><div class="card-body settings-aside"><h3>How setup will work</h3><ol><li>Confirm each mailbox, tenant, aliases and intended business coverage.</li><li>Configure restricted Microsoft 365 access and verify incoming and outgoing capture.</li><li>Test client matching, duplicate handling, private reporting and reconnection.</li><li>Where needed, use server-managed copies of both inbound and outbound mail into a connected intake mailbox.</li></ol><p>Manual recording remains available. A connected Outlook account in ChatGPT does not automatically connect this application.</p><button class="button full-width spaced" data-action="connection-example">See a connection warning</button></div></aside></div>`;}
function noAccess(){return `${heading('This record is not available','Choose an area you can access from the navigation.')}${empty('Access follows the record','This preview hides other executives’ private work and directors’ reporting.',`<a class="button" href="#/dashboard">Back to dashboard</a>`)}`;}
function render(){const [page,id]=route();let content;switch(page){case'directory':content=directory();break;case'clients':content=directory(true);break;case'client':content=orgDetail(id);break;case'prospects':content=prospects();break;case'projects':content=projects();break;case'project':content=projectDetail(id);break;case'tasks':content=tasksPage();break;case'samples':content=samples();break;case'management':content=management();break;case'filing':content=filing();break;case'settings':content=settings();break;default:content=dashboard();}app.innerHTML=layout(content);}

// Forms and event handlers follow. All effects are confined to fictional state.
function field(name,label,value='',type='text',required=true,help=''){return `<div class="field"><label for="f-${name}">${label}</label><input id="f-${name}" name="${name}" type="${type}" value="${e(value)}" ${required?'required':''}>${help?`<small>${help}</small>`:''}</div>`;}
function selectField(name,label,options,value='',help=''){return `<div class="field"><label for="f-${name}">${label}</label><select id="f-${name}" name="${name}">${options.map(o=>{const [v,t]=Array.isArray(o)?o:[o,o];return `<option value="${e(v)}" ${v===value?'selected':''}>${e(t)}</option>`}).join('')}</select>${help?`<small>${help}</small>`:''}</div>`;}
function textField(name,label,value='',required=false){return `<div class="field"><label for="f-${name}">${label}</label><textarea id="f-${name}" name="${name}" ${required?'required':''} dir="auto">${e(value)}</textarea></div>`;}
function ownerOptions(current){return Object.values(people).filter(p=>isDirector(actor)||p.id===actor.id||p.id===current).map(p=>[p.id,p.name]);}
function orgOptions(blank=true){return [...(blank?[['','General / internal work']]:[]),...visible(actor,state.organisations).map(o=>[o.id,o.name])];}
function dialog(title,subtitle,content,footer='',wide=false){lastFocus=document.activeElement;overlay.innerHTML=`<div class="overlay"><section class="dialog ${wide?'wide':''}" role="dialog" aria-modal="true" aria-labelledby="dialog-title" tabindex="-1"><header class="dialog-header"><div><h2 id="dialog-title">${e(title)}</h2><p>${e(subtitle)}</p></div><button class="icon-button" data-action="close" aria-label="Close dialog">${icon('close')}</button></header><div class="dialog-content">${content}</div>${footer?`<footer class="dialog-footer">${footer}</footer>`:''}</section></div>`;document.body.style.overflow='hidden';setTimeout(()=>overlay.querySelector('input:not([type=checkbox]),select,textarea,button')?.focus(),0);}
function formDialog(type,title,subtitle,body,submit='Save example',extra={},wide=false){modal={type,...extra};dialog(title,subtitle,`<form id="dialog-form"><div id="form-error" role="alert"></div>${body}</form>`,`${btn('Cancel','close')}<button class="button primary" type="submit" form="dialog-form">${submit}</button>`,wide);}
function close(){overlay.innerHTML='';modal=null;document.body.style.overflow='';if(lastFocus?.isConnected)lastFocus.focus();}
function formError(message){const target=document.getElementById('form-error');if(target){target.className='form-error';target.textContent=message;target.scrollIntoView({block:'nearest'});}else toast(message);}
function newTask(org='',project=''){formDialog('add-task','New task','Make the next action clear and accountable.',`${field('title','What needs to happen?','')}${selectField('org','Related organisation',orgOptions(),org)}<div class="form-grid">${selectField('owner','Accountable owner',ownerOptions(),isDirector(actor)?'sameh':actor.id)}${field('due','Due date','2026-11-09','date')}${selectField('priority','Priority',['Normal','High','Urgent'])}${selectField('audience','Who can see it?',isDirector(actor)?[['owner','Owner and directors'],['shared','Shared team'],['directors','Directors only']]:[['owner','Me and directors']])}</div><div class="spaced">${textField('detail','Notes')}</div>`,'Create task',{project});}
function taskDialog(id){const t=byId(state.tasks,id);if(!canReadLinked(actor,t,state))return;formDialog('edit-task',t.title,`${person(t.owner)} · ${t.org?orgName(t.org):byId(state.projects,t.project)?.name||'General work'}`,`${tag(audience(t),t.audience==='directors'?'rose':'')}<div class="notice">${e(t.detail||'No additional notes.')}${t.source?`<br><button class="text-btn" type="button" data-action="email" data-id="${t.source}">Open source communication →</button>`:''}</div><div class="form-grid">${selectField('status','Status',['To do','In progress','Waiting','Blocked','Cancelled'],t.status==='Done'?'To do':t.status)}${field('due','Due / review date',t.due,'date')}</div><div class="spaced">${textField('reason','Reason / current position',t.detail)}${field('waitingOn','Waiting on',t.waitingOn||'','text',false)}</div><p class="small-text muted">Original commitment: ${date(t.originalDue||t.due)}. A changed date keeps the original commitment in history.</p>`,'Save task',{id});overlay.querySelector('.dialog-footer').insertAdjacentHTML('afterbegin',btn('Complete task','complete-task',id,'soft'));}
function completeDialog(id){const t=byId(state.tasks,id);if(!canReadLinked(actor,t,state)||t.status==='Done')return;formDialog('complete-task','Complete this action',t.title,`<div class="note-box">Keep the next step clear for ${e(t.org?orgName(t.org):byId(state.projects,t.project)?.name||'this work')}.</div>${selectField('nextMode','What happens next?',[['next','Set the next action'],['waiting','Wait for a response'],['closed','No further action for this task']])}<div id="next-fields">${field('next','Next action','')}${field('due','Due / review date','2026-11-09','date')}</div>${textField('reason','Completion note / reason','',true)}`,'Complete & save',{id});}
function orgDialog(id){const o=id?byId(state.organisations,id):null;if(o&&!canRead(actor,o))return;formDialog(o?'edit-org':'add-org',o?'Edit organisation':'Add organisation','One record from research to prospect to client.',`${field('name','Organisation name',o?.name)}<div class="form-grid">${selectField('type','Organisation type',['School','School group','Business','Supplier','Partner'],o?.type||'School')}${selectField('country','Country',['UAE','Saudi Arabia'],o?.country||(actor.country==='Saudi Arabia'?'Saudi Arabia':'UAE'))}${field('city','City',o?.city,'text',false)}${selectField('status','Relationship',['Research','Prospect','Client','Past client'],o?.status||(route()[0]==='clients'?'Client':'Research'))}${selectField('owner','Owner',ownerOptions(o?.owner),o?.owner||(isDirector(actor)?'sameh':actor.id))}${field('due','Next action date',o?.due,'date',false)}</div><div class="spaced">${field('next','Next action',o?.next,'text',false)}</div><div class="form-grid">${field('contact','Contact name',o?.contact,'text',false)}${field('email','Contact email',o?.email,'email',false)}${field('position','Contact role',o?.position,'text',false)}${field('phone','Telephone',o?.phone,'text',false)}</div><div class="spaced">${textField('notes','Relationship notes',o?.notes)}</div>`,'Save organisation',{id});}
function opportunityDialog(id){const o=id?byId(state.opportunities,id):null;if(o&&!canRead(actor,o))return;formDialog('opportunity',o?'Update opportunity':'New opportunity','Track a specific piece of potential work.',`${selectField('org','Organisation',orgOptions(false),o?.org)}${field('title','Opportunity scope',o?.title)}<div class="form-grid">${selectField('owner','Owner',ownerOptions(o?.owner),o?.owner||(isDirector(actor)?'sameh':actor.id))}${selectField('stage','Stage',stages,o?.stage||'Identified')}${field('value','Estimated annual value',o?.value||'','number',false)}${selectField('currency','Currency',['AED','SAR','GBP'],o?.currency||'AED')}${field('due','Next action / review date',o?.due||'2026-11-09','date')}</div><div class="spaced">${field('next','Next action',o?.next)}${textField('reason','Outcome evidence / reason (required for Won or Lost)')}</div><div class="notice">Winning preserves the organisation and its history. Confirm the outcome deliberately; an email alone does not win an opportunity.</div>`,'Save opportunity',{id});}
function newProject(){formDialog('add-project','New project','For client delivery or internal work.',`${field('name','Project name')}${textField('description','What will this project achieve?','',true)}<div class="form-grid">${selectField('owner','Accountable owner',ownerOptions(),isDirector(actor)?'sameh':actor.id)}${selectField('country','Country',['UAE','Saudi Arabia'],actor.country==='Saudi Arabia'?'Saudi Arabia':'UAE')}${field('target','Target date','2026-12-01','date')}${selectField('audience','Who can see it?',isDirector(actor)?[['owner','Owner and directors'],['shared','Shared team'],['directors','Directors only']]:[['owner','Me and directors']])}</div><div class="spaced">${field('next','First milestone')}</div>`,'Create project');}
function emailDialog(id){const m=byId(state.messages,id);if(!canReadLinked(actor,m,state))return;modal={type:'email',id};dialog(m.subject,'Example communication · not a live Outlook message',`${tag(m.state,statusTone(m.state))} ${tag(audience(m),m.audience==='directors'?'rose':'')}<dl class="message-details spaced"><dt>From</dt><dd>${e(m.from)}</dd><dt>Mailbox</dt><dd>${e(m.mailbox)}</dd><dt>Recorded</dt><dd>${fullDate(m.date)}</dd><dt>Direction</dt><dd>${e(m.direction)}</dd><dt>Linked to</dt><dd>${m.org?e(orgName(m.org)):'Needs filing'}</dd></dl><div class="message-body" dir="auto">${e(m.body)}</div>${m.meaningful===false?'<div class="coverage">An acknowledgement is recorded. The requested dates are still outstanding.</div>':''}<div class="notice">A recorded reply is evidence of communication, not proof that the underlying task is complete.</div>`,`${!m.org?btn('File to a record','file-email',id):btn('Update follow-up','response',id)}${btn('Suggest a task','email-task',id,'primary')}`);}
function responseDialog(id){const m=byId(state.messages,id);if(!canReadLinked(actor,m,state))return;formDialog('response','Update follow-up',m.subject,`${selectField('state','Conversation status',['Needs our response','Waiting for their response','Follow-up scheduled','No action required'],m.state)}${textField('reason','Note / reason','',true)}`,'Save status',{id});}
function fileDialog(id){const m=byId(state.messages,id);if(!canReadLinked(actor,m,state))return;formDialog('file-email','File this communication',m.subject,`<div class="message-body">${e(m.body)}</div>${selectField('org','Correct organisation',orgOptions(false))}<div class="notice">Message access stays ${e(audience(m).toLowerCase())}. Choosing a shared organisation does not share the original email more widely.</div>`,'Confirm filing',{id});}
function manualEmail(org){formDialog('manual-email','Record an example email','Try the manual capture workflow using fictional content.',`${selectField('org','Organisation',[['','Leave in Needs filing'],...orgOptions(false)],org)}${field('from','Sender / recipient name','Example contact')}${field('subject','Subject')}${selectField('direction','Direction',['Incoming','Outgoing'])}${textField('body','Message or summary','',true)}<div class="notice">This preview records text locally. Production email upload and forwarding will preserve source metadata and attachments.</div>`,'Record example');}
function productDialog(id){const p=byId(state.products,id);if(!p)return;modal={type:'product',id};const units=state.units.filter(u=>u.product===id);dialog(p.name,p.ref+' · '+p.colour,`<div class="product-detail-art">${garment(p)}</div><div class="row-bottom">${p.tags.map(t=>tag(t)).join('')}${tag(p.supply,'blue')}</div><dl class="detail-list spaced"><div class="pair"><div><dt>RRP without logo</dt><dd>${money(p.rrp,p.currency)}</dd></div><div><dt>RRP with logo</dt><dd>${money(p.rrpLogo,p.currency)}</dd></div><div><dt>Expected production</dt><dd>${p.lead}</dd></div></div></dl><div class="notice">RRP ${p.tax}. Illustration only; product photographs can be uploaded in the application build.</div><h3 class="spaced">Physical samples</h3><div class="unit-list">${units.map(u=>{const details=canSeeUnitDetail(actor,u,state.organisations);return `<div class="unit-row"><div><strong>Size ${e(u.size)}${u.branded?' · with logo':''}</strong><small>${details?e(u.id)+' · '+e(u.holder):'Held elsewhere · details restricted'}</small></div><div>${tag(u.status,statusTone(u.status))}${details&&u.due?`<small>Return ${date(u.due)}</small>`:''}</div></div>`}).join('')}</div>${isDirector(actor)?`<div class="note-box"><strong>Internal commercial details · directors only</strong><dl class="detail-list spaced"><div><dt>Supplier / country</dt><dd>${e(p.supplier)} · ${e(p.supplierCountry)}</dd></div><div><dt>Manufacturer code</dt><dd>${p.manufacturerCode}</dd></div><div><dt>Cost without / with logo</dt><dd>${money(p.cost,p.currency)} / ${money(p.costLogo,p.currency)}</dd></div></dl></div>`:''}`,`${btn('Take internally','product-take',id)}${btn('Issue to client','product-issue',id,'primary')}`);}
function moveDialog(kind,product){const choices=state.units.filter(u=>(!product||u.product===product)&&canSeeUnitDetail(actor,u,state.organisations)&&(kind==='take'?u.status==='Available':kind==='issue'?u.status==='Available'||u.status==='With colleague'&&(isDirector(actor)||u.owner===actor.id):['With client','With colleague'].includes(u.status)));const titles={take:['Take samples','Record colleague custody. No client delivery note or email.'],issue:['Issue samples to a client','Record the handover and generate a client-safe example note.'],return:['Return samples','Select the exact items returned. Other loaned items stay outstanding.']};let controls=kind==='take'?selectField('holder','Colleague taking the samples',ownerOptions(),actor.id):kind==='issue'?`${selectField('org','Client',orgOptions(false).filter(([id])=>byId(state.organisations,id)?.status!=='Research'))}${field('recipient','Delivery-note recipient','Example recipient')}`:selectField('location','Return location',['Sharjah base','Riyadh base']);if(kind!=='return')controls+=field('due','Expected return date','2026-11-13','date');formDialog('move',titles[kind][0],titles[kind][1],`${controls}<div class="section-label spaced">Choose physical samples</div>${choices.map(u=>{const p=byId(state.products,u.product);return `<label class="check-row"><input type="checkbox" name="units" value="${u.id}"><span class="check-content"><strong>${e(p.name)} · ${e(u.size)}</strong><small>${p.ref} · ${p.colour} · ${u.id} · ${e(u.holder)}</small></span>${tag(u.branded?'With logo':'No logo')}</label>`}).join('')||empty('No eligible samples','Choose a different movement or product.')}<div class="notice">${kind==='issue'?'Only SUD reference, approved product name, size, colour, quantity and RRP appear on the note. This example will not send an email.':kind==='return'?'Each selected item returns to the chosen base. The original handover remains in history.':'An internal movement never creates a client email. Record a separate client issue if samples are left with the client.'}</div>`,kind==='issue'?'Confirm example handover':kind==='take'?'Record internal movement':'Confirm return',{kind,product},true);}
function noteDialog(note){modal={type:'note'};dialog('Client delivery note',note.number+' · fictional example',`<div class="notice">Generated from approved public fields only. No email has been sent. You can print this example or save it as a PDF using your browser.</div><article class="safe-note" id="safe-note"><div class="letterhead"><div><div class="sud-word">SUD</div><p>School Uniform Direct<br>Middle East · SAMPLE DOCUMENT</p></div><div><h3>Sample delivery note</h3><p>${e(note.number)}<br>${fullDate(note.date)}</p></div></div><div class="note-addresses"><div><small>ISSUED TO</small><strong>${e(note.client)}</strong><br>${e(note.recipient)}</div><div><small>EXPECTED RETURN</small>${fullDate(note.expectedReturn)}<br>Sample loan · return required</div></div><div class="table-wrap"><table class="table"><thead><tr><th>SUD ref</th><th>Product</th><th>Size</th><th>Colour</th><th>Qty</th><th>RRP</th></tr></thead><tbody>${note.lines.map(l=>`<tr><td>${e(l.reference)}</td><td>${e(l.product)}</td><td>${e(l.size)}</td><td>${e(l.colour)}</td><td>${l.quantity}</td><td>${money(l.rrp,l.currency)}</td></tr>`).join('')}</tbody></table></div><div class="note-terms">${[...new Set(note.lines.map(l=>l.tax))].map(e).join('; ')}. RRP is provided for reference. This document is not an invoice or a request for payment.<br>Please return the listed samples by the expected return date.<br><br>Fictional design preview. Business issuing details and delivery address will be confirmed in the live system.</div></article>`,`${btn('Close','close')}<button class="button primary" data-action="print">${icon('print')}Print / save PDF</button>`,true);}
function sharingDialog(id){const o=byId(state.organisations,id);if(!isDirector(actor)||!o)return;formDialog('sharing','Record sharing',o.name,`${selectField('audience','Who can access this organisation?',[['owner',`${person(o.owner)} and directors`],['shared','Sameh, Latif and directors'],['directors','Directors only']],o.audience)}<div class="notice">Sharing the organisation does not widen the audience of existing restricted messages, notes or commercial discussions.</div>`,'Save sharing',{id});}
function help(){modal={type:'help'};dialog('Walk through the hub','A small number of connected workflows.',`<div class="note-box">This is an interactive design preview with fictional data. Role switching demonstrates the intended views; production identity and permissions will be enforced on the server. No live mailboxes are connected.</div><div class="help-steps">${[['1. Start with the priorities','Open a task, change its review date or complete it with a next action.','/dashboard'],['2. Follow the client history','Open Cedar School to see incoming mail, a recorded reply and the linked work.','/client/cedar'],['3. Check access','Use Preview as to switch between Alex, Bilal, Sameh and Latif. The Riyadh refit is shared; private work and reports are separate.','/projects'],['4. Try the sample handover','Take samples internally, issue selected items to a client, view the safe delivery note and return one item.','/samples'],['5. Read the management brief','Directors can inspect source communications and see coverage gaps.','/management']].map(([title,body,path])=>`<div class="help-step"><h3>${title}</h3><p>${body}</p><button class="text-btn" data-action="help-go" data-id="${path}">Open this area →</button></div>`).join('')}</div><div class="notice">Example changes stay on this device. Reset examples restores the original walkthrough. Mobile layouts are included.</div>`,btn('Start exploring','close','','primary'));}
function connectionExample(){modal={type:'connection-example'};dialog('Connection needs attention','Illustrative error state — not a live mailbox incident',`<div class="coverage">${icon('alert')}<div>Example mailbox disconnected<small>Incoming and outgoing coverage may be incomplete after 09:10.</small></div></div><dl class="detail-list"><div><dt>What staff see</dt><dd>Last recorded contact, with a visible coverage warning.</dd></div><div><dt>What directors see</dt><dd>A reporting gap. No inference that the executive has stopped working.</dd></div><div><dt>Recovery</dt><dd>An authorised administrator restores the connection. Reconciliation catches up missing messages without duplicating tasks.</dd></div></dl><div class="notice">Manual recording remains available while the connection is repaired.</div>`,btn('Close example','close','','primary'));}

function onAction(action,id,el){
  switch(action){
    case'menu':mobileOpen=!mobileOpen;render();break;
    case'help':help();break;
    case'help-go':close();go(id);break;
    case'close':close();break;
    case'reset':formDialog('reset','Reset the examples?','This only resets fictional data saved on this device.','<p class="info-text">Your example tasks, notes and sample movements will be replaced with the original demonstration. No real business records are involved.</p>','Reset examples');break;
    case'owner-filter':ownerFilter=id;render();break;
    case'directory-filter':directoryFilter=id;render();break;
    case'task-filter':taskFilter=id;render();break;
    case'mail-filter':mailFilter=id;render();break;
    case'sample-tab':sampleTab=id;listQuery='';render();break;
    case'record-tab':recordTab=id;render();break;
    case'open-org':close();go('/client/'+id);break;
    case'back-clients':go('/directory');break;
    case'back-projects':go('/projects');break;
    case'stat':if(id==='tasks'){taskFilter=el.dataset.label==='Due today'?'Today':'Overdue';go('/tasks');}else if(id==='filing'){mailFilter='Open requests';go('/filing');}else{sampleTab='On loan';go('/samples');}break;
    case'add-task':newTask(id);break;
    case'project-task':newTask(byId(state.projects,id)?.org||'',id);break;
    case'task':taskDialog(id);break;
    case'complete-task':completeDialog(id);break;
    case'add-org':orgDialog();break;
    case'edit-org':orgDialog(id);break;
    case'add-opportunity':opportunityDialog();break;
    case'opportunity':opportunityDialog(id);break;
    case'add-project':newProject();break;
    case'email':emailDialog(id);break;
    case'response':responseDialog(id);break;
    case'file-email':fileDialog(id);break;
    case'manual-email':manualEmail(id);break;
    case'email-task':{const m=byId(state.messages,id);if(!canReadLinked(actor,m,state))return;newTask(m.org||'');modal.source=id;document.getElementById('f-title').value='Follow up: '+m.subject;break;}
    case'add-note':{const o=byId(state.organisations,id);if(!canRead(actor,o))return;formDialog('add-note','Add an activity note',o.name,`${selectField('kind','Activity type',['Note','Meeting','Call','Visit','WhatsApp summary'])}${textField('body','What happened and what was agreed?','',true)}${isDirector(actor)?selectField('audience','Visibility',[['record','Same as the organisation'],['directors','Directors only']]):''}`,'Save note',{id});break;}
    case'product':productDialog(id);break;
    case'product-take':moveDialog('take',id);break;
    case'product-issue':moveDialog('issue',id);break;
    case'move':moveDialog(id);break;
    case'note':{const note=state.documents.find(n=>n.number===id);if(note&&visible(actor,state.organisations).some(o=>o.name===note.client))noteDialog(note);break;}
    case'print':window.print();break;
    case'sharing':sharingDialog(id);break;
    case'connection-example':connectionExample();break;
  }
}
function submit(form){const d=Object.fromEntries(new FormData(form));const current={...modal};const uuid=()=>crypto.randomUUID();try{
  switch(current.type){
    case'reset':state=seed();break;
    case'add-task':{const org=byId(state.organisations,d.org),project=byId(state.projects,current.project);if(org&&!canRead(actor,org))throw new Error('Organisation unavailable.');if(d.due<TODAY)throw new Error('Choose today or a future due date for this new task.');const t={id:uuid(),title:d.title.trim(),org:d.org||null,project:current.project||null,owner:d.owner,audience:d.audience,due:d.due,originalDue:d.due,status:'To do',priority:d.priority,detail:d.detail,source:current.source||null};if(org&&org.audience!=='shared'&&t.audience==='shared')throw new Error('Share the organisation first, or keep this task with its owner and directors.');if(current.source){const source=byId(state.messages,current.source);t.audience=source.audience;if(source.audience==='directors'&&!isDirector(people[t.owner]))throw new Error('Assign this private source to a director, or create a separately reviewed safe action.');}state.tasks.push(t);if(org&&org.status!=='Research'){org.next=t.title;org.due=t.due;}if(project)project.next=t.title;break;}
    case'edit-task':{const t=byId(state.tasks,current.id);if(!canReadLinked(actor,t,state))throw new Error('Task unavailable.');setTaskState(t,d.status,{date:d.due,reason:d.reason,waitingOn:d.waitingOn});break;}
    case'complete-task':{const t=byId(state.tasks,current.id);if(!canReadLinked(actor,t,state))throw new Error('Task unavailable.');if(d.nextMode!=='closed'&&(!d.next?.trim()||!d.due))throw new Error('Set the next action and date.');if(d.nextMode!=='closed'&&d.due<TODAY)throw new Error('Choose today or a future review date.');t.status='Done';t.completionNote=d.reason;if(d.nextMode!=='closed')state.tasks.push({...t,id:uuid(),title:d.next.trim(),status:d.nextMode==='waiting'?'Waiting':'To do',due:d.due,originalDue:d.due,detail:d.reason,completionNote:null});const o=byId(state.organisations,t.org);if(o&&o.next===t.title){o.next=d.nextMode==='closed'?'No further action recorded':d.next.trim();o.due=d.nextMode==='closed'?null:d.due;}const p=byId(state.projects,t.project);if(p&&p.next===t.title)p.next=d.nextMode==='closed'?'Review next project milestone':d.next.trim();break;}
    case'add-org':case'edit-org':{if(d.status!=='Research'&&(!d.next?.trim()||!d.due))throw new Error('Active relationships need a next action and date.');let o=current.id?byId(state.organisations,current.id):null;if(o&&!canRead(actor,o))throw new Error('Organisation unavailable.');if(!o){o={id:uuid(),audience:'owner',colour:'rose',lastContact:null,contract:'',review:''};state.organisations.push(o);}if(current.id&&!isDirector(actor))d.owner=o.owner;Object.assign(o,d,{name:d.name.trim(),short:d.name.split(' ').slice(0,2).map(s=>s[0]).join('').toUpperCase(),due:d.due||null});if(!o.next)o.next='Not yet approached';break;}
    case'opportunity':{const org=byId(state.organisations,d.org);if(!canRead(actor,org))throw new Error('Choose an accessible organisation.');if(['Won','Lost'].includes(d.stage)&&!d.reason?.trim())throw new Error('Record the evidence or reason for this outcome.');if(Number(d.value)<0)throw new Error('Estimated value must be zero or more.');const old=current.id?byId(state.opportunities,current.id):null;if(old&&!canRead(actor,old))throw new Error('Opportunity unavailable.');if(old&&!isDirector(actor))d.owner=old.owner;const o={...(old||{id:uuid()}),...d,value:Number(d.value)||0,audience:org.audience,country:org.country};if(old)Object.assign(old,o);else state.opportunities.push(o);if(d.stage==='Won')org.status='Client';else if(org.status==='Research')org.status='Prospect';org.next=d.next;org.due=d.due;break;}
    case'add-project':state.projects.push({...d,id:uuid(),org:null,status:'Planned',milestones:[[d.next,d.target,'Upcoming']]});break;
    case'add-note':{const org=byId(state.organisations,current.id);if(!canRead(actor,org))throw new Error('Organisation unavailable.');state.notes.push({id:uuid(),org:org.id,kind:d.kind,body:d.body,author:actor.id,owner:actor.id,audience:d.audience==='directors'?'directors':org.audience==='owner'?'owner':org.audience,date:TODAY});if(org.audience==='owner')state.notes.at(-1).owner=org.owner;break;}
    case'response':{const m=byId(state.messages,current.id);if(!canReadLinked(actor,m,state))throw new Error('Message unavailable.');m.state=d.state;m.statusNote=d.reason;break;}
    case'file-email':{const m=byId(state.messages,current.id),o=byId(state.organisations,d.org);if(!canRead(actor,m)||!canRead(actor,o))throw new Error('Message or organisation unavailable.');m.org=o.id;m.state='Needs our response';m.manualMatch=true;break;}
    case'manual-email':{const org=byId(state.organisations,d.org);if(org&&!canRead(actor,org))throw new Error('Organisation unavailable.');state.messages.push({...d,id:uuid(),org:d.org||null,owner:org?.owner||actor.id,audience:org?.audience||(isDirector(actor)?'directors':'owner'),mailbox:'Manual example capture',date:TODAY+'T12:00:00',state:d.org?(d.direction==='Outgoing'?'Waiting for their response':'Needs our response'):'Needs filing',meaningful:true});break;}
    case'sharing':{if(!isDirector(actor))throw new Error('Director access required.');byId(state.organisations,current.id).audience=d.audience;break;}
    case'move':{const note=moveSamples(state,actor,{kind:current.kind,ids:new FormData(form).getAll('units'),holder:people[d.holder],org:d.org,recipient:d.recipient,due:d.due,location:d.location,date:TODAY});close();save('Example movement recorded. No email sent.');if(note)noteDialog(note);return;}
  }
  close();save(current.type==='reset'?'Original examples restored.':'Example saved.');
}catch(error){formError(error.message);}}
document.addEventListener('click',event=>{const target=event.target.closest('[data-action]');if(target){event.preventDefault();onAction(target.dataset.action,target.dataset.id||'',target);}else if(event.target.classList.contains('overlay'))close();else if(!event.target.closest('.searchbox')){const r=document.getElementById('search-results');if(r)r.innerHTML='';}});
document.addEventListener('submit',event=>{if(event.target.id==='dialog-form'){event.preventDefault();submit(event.target);}});
document.addEventListener('change',event=>{const {id,value}=event.target;if(id==='role'){actor=people[value]||people.alex;ownerFilter='All accessible';region='All regions';close();render();}if(id==='region'){region=value;render();}if(id==='f-nextMode'){const wrap=document.getElementById('next-fields');const closed=value==='closed';wrap.hidden=closed;wrap.querySelectorAll('input').forEach(input=>{input.required=!closed;});}});
document.addEventListener('input',event=>{if(event.target.id==='list-search'){const position=event.target.selectionStart;listQuery=event.target.value;render();const input=document.getElementById('list-search');input?.focus();try{input?.setSelectionRange(position,position);}catch{}}if(event.target.id==='global-search'){const q=event.target.value.trim().toLowerCase();const results=document.getElementById('search-results');if(q.length<2){results.innerHTML='';return;}const found=[...visible(actor,state.organisations).map(o=>({label:o.name,detail:o.type+' · '+o.city,url:'/client/'+o.id})),...visible(actor,state.projects).map(p=>({label:p.name,detail:'Project · '+person(p.owner),url:'/project/'+p.id})),...state.products.map(p=>({label:p.name+' · '+p.ref,detail:'Sample catalogue',url:'/samples'}))].filter(r=>`${r.label} ${r.detail}`.toLowerCase().includes(q)).slice(0,6);results.innerHTML=`<div class="search-results">${found.map(r=>`<a href="#${r.url}">${e(r.label)}<small>${e(r.detail)}</small></a>`).join('')||'<div class="empty" style="padding:18px">No accessible matches.</div>'}</div>`;}});
document.addEventListener('keydown',event=>{if(event.key==='Escape'){close();document.getElementById('search-results')?.replaceChildren();}if(event.key==='Tab'&&overlay.firstChild){const items=[...overlay.querySelectorAll('button:not([disabled]),a[href],input:not([disabled]),select:not([disabled]),textarea:not([disabled])')].filter(el=>el.getClientRects().length);const first=items[0],last=items.at(-1);if(event.shiftKey&&document.activeElement===first){event.preventDefault();last?.focus();}else if(!event.shiftKey&&document.activeElement===last){event.preventDefault();first?.focus();}}});
window.addEventListener('hashchange',()=>{close();listQuery='';mobileOpen=false;render();window.scrollTo(0,0);});
render();
